import{_ as o}from"./chunks/image1.Bk1JI49V.js";import{_ as r}from"./chunks/image2.UYnXny4D.js";import{_ as n}from"./chunks/image3.z0vX6Nw7.js";import{_ as e}from"./chunks/image4.Co4Tm3RS.js";import{_ as l}from"./chunks/image5.NlMtFgFW.js";import{_ as a}from"./chunks/image6.DPvKUHqc.js";import{_ as p,c as g,o as s,ae as i}from"./chunks/framework.B8KKhRA6.js";const S=JSON.parse('{"title":"4-2. 난임치료휴가 운영지침","description":"","frontmatter":{"title":"4-2. 난임치료휴가 운영지침"},"headers":[],"relativePath":"manual/4-2._난임치료휴가_운영지침.md","filePath":"manual/4-2._난임치료휴가_운영지침.md"}'),u={name:"manual/4-2._난임치료휴가_운영지침.md"};function c(h,t,q,_,d,b){return s(),g("div",null,t[0]||(t[0]=[i('<blockquote><p>&quot;문화와 예술로 행복한 서울 만들기&quot;</p></blockquote><p>+-------------------+--------------------------------------------------+ | &gt; 문서번호 | &gt; 인사팀-1324 | +:=================:+==================================================+ | &gt; 보존기간 | &gt; 준영구 | +-------------------+--------------------------------------------------+ | &gt; 결재일자 | &gt; 2024. 04. 17. | +-------------------+--------------------------------------------------+ | &gt; 공개여부 | &gt; 공개 | +-------------------+--------------------------------------------------+ | &gt; 방침번호 | &gt; 대표이사 방침 제(159)호 | +-------------------+--------------------------------------------------+</p><p>+---------------------------------------------------------------------------------------------------------------+----------------------------------------------------------------------------------------------------------------------------+---------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------------------------------------------------------------------+ | &gt; ★사원 | &gt; 팀장 | &gt; 본부장 | &gt; 대표이사 | :============================================================================================================:+ | &gt; <img src="'+o+'" alt="" width="0.42205161854768153in" height="0.125in"> | &gt; <img src="'+r+'" alt="" width="0.4095909886264217in" height="0.11666557305336833in"> | &gt; <img src="'+n+'" alt="" width="0.5669652230971128in" height="0.4059372265966754in"> | &gt; <strong>04/17</strong> | | | | | &gt; | | | | | &gt; <img src="'+e+'" alt="" width="0.4065540244969379in" height="0.125in"> | +---------------------------------------------------------------------------------------------------------------+----------------------------------------------------------------------------------------------------------------------------+---------------------------------------------------------------------------------------------------------------------------+--------------------------------------------------------------------------------------------------------------+ | &gt; 협 조 | | +---------------------------------------------------------------------------------------------------------------+-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+ | | +---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+</p><blockquote><p><strong>서울문화재단 난임치료휴가 운영지침</strong></p></blockquote><p><img src="'+l+'" alt="" width="3.436900699912511in" height="0.5166666666666667in"></p><h1 id="서울문화재단-난임치료휴가-운영지침" tabindex="-1">서울문화재단 난임치료휴가 운영지침 <a class="header-anchor" href="#서울문화재단-난임치료휴가-운영지침" aria-label="Permalink to &quot;서울문화재단 난임치료휴가 운영지침&quot;">​</a></h1><blockquote><p><strong>일‧가정 양립 지원을 위해 서울문화재단 복무규정을 개정하였으며, 이에 따른 난임치료휴가 사용에 대한 세부 운영지침을 마련하고자 함</strong></p></blockquote><h2 id="기본개요" tabindex="-1">기본개요 <a class="header-anchor" href="#기본개요" aria-label="Permalink to &quot;기본개요&quot;">​</a></h2><h3 id="추진-근거" tabindex="-1">추진 근거 <a class="header-anchor" href="#추진-근거" aria-label="Permalink to &quot;추진 근거&quot;">​</a></h3><blockquote><p>Ⅰ</p><p><strong>ㅇ 서울문화재단 복무규정 제30조의3(특별휴가)</strong></p><p><strong>제30조의3(특별휴가)</strong> ③ 인공수정 또는 체외수정 등 난임치료 시술을 받는 직원은 다음 각 호의 구분에 따라 난임치료휴가를 받을 수 있다. &lt;개정 2024. 2. 27.&gt;</p></blockquote><ol><li>여성직원: 다음 각 목의 어느 하나에 해당하는 경우 해당 목에서 정한 기간 &lt;개정 2024. 2. 27.&gt; 가. 인공수정 등 시술을 받는 경우: 총 2일(시술 당일 1일과 시술일 전날, 시술일 후 2일 이내이거나 시술 관련 진료일 중에 1일) &lt;개정 2024. 2. 27.&gt;</li></ol><blockquote><p>나. 동결 보존된 배아를 이식하는 체외수정 시술을 받는 경우: 총 3일(시술 당일에 1일과 시술일 전날, 시술일 후 2일 이내이거나 시술 관련 진료일 중에 2일) &lt;개정 2024. 2. 27.&gt;</p><p>다. 난자 채취를 하여 체외수정 시술을 받는 경우: 총 4일(난자 채취일에 1일, 시술 당일에 1일과 시술일 전날, 난자 채취일 전날, 시술일 후 2일 이내, 난자 채취일 후 2일 이내이거나 시술 관련 진료일 중에 2일) &lt;개정 2024. 2. 27.&gt;</p></blockquote><ol start="2"><li>남성직원: 정자 채취일에 1일&lt;개정 2024. 2. 27.&gt;</li></ol><blockquote><p><strong>ㅇ 인사팀-2433(2023. 8. 31.) &quot;2023년 복무ㆍ근태 관리 및 개선 계획(안)&quot;</strong></p></blockquote><h3 id="주요-개선-사항" tabindex="-1">주요 개선 사항 <a class="header-anchor" href="#주요-개선-사항" aria-label="Permalink to &quot;주요 개선 사항&quot;">​</a></h3><blockquote><p><strong>ㅇ 유급휴가일수 확대</strong></p></blockquote><p><strong>▶</strong></p><p><strong>개선</strong></p><p>+-----------------------------------------------------------------------+ | &gt; <strong>기존</strong> | +=======================================================================+ | &gt; 연간 3일 (최초 1일 유급) | +-----------------------------------------------------------------------+ | &gt; 남성 직원 1일 (최초 1일 유급) | +-----------------------------------------------------------------------+</p><p>+------------------------------+-----------------+-----------------------+ | &gt; <strong>시술 구분</strong> | &gt; <strong>휴가 일수</strong> | &gt; <strong>비고</strong> | +:============================:+:===============:+=======================+ | &gt; 인공수정 | &gt; 총 2일 | &gt; 유급 | +------------------------------+-----------------+ | | &gt; 체외수정(동결배아) | &gt; 총 3일 | | +------------------------------+-----------------+ | | &gt; 체외수정(난자채취) | &gt; 총 4일 | | +------------------------------+-----------------+ | | &gt; 정자 채취일 | &gt; 총 1일 | | +------------------------------+-----------------+-----------------------+</p><h2 id="세부운영지침" tabindex="-1">세부운영지침 <a class="header-anchor" href="#세부운영지침" aria-label="Permalink to &quot;세부운영지침&quot;">​</a></h2><blockquote><p>Ⅱ</p></blockquote><h3 id="난임치료시술별-휴가사용일" tabindex="-1">난임치료시술별 휴가사용일 <a class="header-anchor" href="#난임치료시술별-휴가사용일" aria-label="Permalink to &quot;난임치료시술별 휴가사용일&quot;">​</a></h3><blockquote><p><strong>ㅇ 여성직원의 경우</strong></p></blockquote><ul><li><strong>인공수정 등 시술을 받는 경우</strong>: 시술을 할 때마다 총 2일의 휴가를 부여받을 수 있음. 이 경우 **[시술일 당일을 반드시 포함]{.underline}**하고, 나머지 1일은 시술일 전날, 시술 후 2일 이내 또는 인공수정시술을 위하여 반드시 수반되는 병원진료일 중에</li></ul><blockquote><p>선택할 수 있음.</p></blockquote><ul><li><p><strong>동결 보전된 배아를 이식하는 체외수정 시술을 받는 경우:</strong> 시술을 할 때마다 총 3일의 휴가를 부여받을 수 있음. 이 경우 **[시술일 당일을 반드시 포함]{.underline}**하고, 나머지 2일은 시술일 전날, 시술 후 2일 이내 또는 **[체외수정시술을 위하여]{.underline} [반드시 수반되는 병원진료일 중에 선택]{.underline}**할 수 있음.</p></li><li><p>**난자를 채취하여 체외수정 시술을 받는 경우: [시술을 할 때마다 총 4일의]{.underline} [휴가를 부여]{.underline}**받을 수 있음. 이 경우 **[난자 채취일 당일과 시술일 당일을 반드시]{.underline} [포함]{.underline}**하고, 나머지 2일은 시술일 전날, 시술 후 2일 이내 또는 체외수정 시술을 위하여 반드시 수반되는 병원진료일 중에 선택할 수 있음.</p></li></ul><blockquote><p><img src="'+a+'" alt="" width="1.1959153543307086in" height="1.046874453193351in">※ 의사와의 단순 상담만을 위한 병원진료일은 사용 불가</p><p><strong>&lt;난임치료시술별 휴가사용일&gt;</strong></p></blockquote><p>난자채취 포함시 선택가능일</p><p><strong>상</strong></p><p><strong>담</strong></p><p><strong>일</strong></p><p><strong>①</strong></p><p><strong>병원</strong></p><p><strong>진료일</strong></p><p><strong>② Ⓐ ③</strong></p><p>Ⓐ-1 <strong>난자</strong> Ⓐ+1</p><p>일 <strong>채취일</strong> 일</p><blockquote><p><strong>④</strong></p></blockquote><p>Ⓐ+</p><blockquote><p>2일</p></blockquote><p>...</p><p><strong>⑤</strong></p><p>Ⓑ-1</p><p>일</p><p><strong>Ⓑ</strong></p><p><strong>시술일</strong></p><p><strong>⑥ ⑦</strong></p><p>Ⓑ+1 Ⓑ+2</p><p>일 일</p><ul><li><p>인공수정 시술 시: Ⓑ 1일 부여, ①, ⑤~⑦ 중 1일 선택 가능</p></li><li><p>동결 보존 배아를 이식하는 체외수정 시술 시: Ⓑ 1일 부여, ①, ⑤~⑦ 중 2일 선택 가능</p></li><li><p>난자를 채취하는 체외수정 시술 시: Ⓐ Ⓑ 각 1일 부여, ①~⑦ 중 2일 선택 가능</p></li></ul><p>※ 단, 초음파 검사, 과배란 유도 등 난임치료시술에 수반되는 병원진료만 사용 가능(상담일 사용불가)</p><blockquote><p><strong>ㅇ 남성직원의 경우: 정자 채취일에 1일</strong></p></blockquote><h3 id="근무상황부-상신-방법" tabindex="-1">근무상황부 상신 방법 <a class="header-anchor" href="#근무상황부-상신-방법" aria-label="Permalink to &quot;근무상황부 상신 방법&quot;">​</a></h3><blockquote><p><strong>ㅇ 근태코드 &#39;난임치료휴가&#39; 선택하여 상신 ㅇ 증빙서류 제출</strong></p></blockquote><ul><li><p>난임치료 받은 사실을 증명할 수 있는 서류로, [이력이 포함된 진단서 또는]{.underline} [의사소견서]{.underline} 제출</p></li><li><p>근무상황부 신청내역에서 증빙자료 별도첨부 필수</p></li></ul><h2 id="기타사항" tabindex="-1">기타사항 <a class="header-anchor" href="#기타사항" aria-label="Permalink to &quot;기타사항&quot;">​</a></h2><h3 id="적용례" tabindex="-1">적용례 <a class="header-anchor" href="#적용례" aria-label="Permalink to &quot;적용례&quot;">​</a></h3><blockquote><p>Ⅲ</p><p><strong>ㅇ 본 지침은 복무규정 개정일(2024년 2월 27일) 이후부터 적용</strong></p></blockquote><h3 id="향후-계획" tabindex="-1">향후 계획 <a class="header-anchor" href="#향후-계획" aria-label="Permalink to &quot;향후 계획&quot;">​</a></h3><blockquote><p><strong>ㅇ 공지: 사내 공지사항 게시판을 통한 직원 대상 안내 예정</strong></p><p><strong>관련: 인사팀-2433(2023. 08. 31.) &quot;2023년 복무ㆍ근태 관리 및 개선 계획(안)&quot; 1부. 붙임: 서울문화재단 복무규정 1부. 끝.</strong></p></blockquote>',61)]))}const $=p(u,[["render",c]]);export{S as __pageData,$ as default};
